import {
	declareRpcContract,
	type EdgeBridge,
	type EdgeMethodTable,
	type RpcMethod,
} from "@sand/dune/rpc";

import type { SandThemePreference, SandThemeState } from "../desktop.js";

export interface SandDevCommandResult {
	readonly isOk: boolean;
	readonly exitCode: number | null;
	readonly output: string;
	readonly durationMs: number;
}

export interface SandDevBoxStatus {
	readonly containerName: string;
	readonly isContainerRunning: boolean;
	readonly gatewayUrl: string;
	readonly isGatewayReachable: boolean;
	readonly isHostBusy: boolean;
	readonly latencyMs: number | null;
	readonly detail: string;
}

export interface SandDevBoxHealthCheck {
	readonly isPass: boolean;
	readonly name: string;
	readonly detail: string;
}

export interface SandDevBoxHealth {
	readonly isOk: boolean;
	readonly checks: readonly SandDevBoxHealthCheck[];
	readonly summary: string;
	readonly raw: string;
}

export interface SandDevBoxStoreStatus {
	readonly isStoreEnabled: boolean;
	readonly lastSnapshotMsAgo: number | null;
	readonly manifestEntries: number;
	readonly totalBytes: number;
	readonly copyInOutcome: string;
	readonly detail: string;
}

export interface AttachProdBoxStatus {
	readonly preferred: boolean;
	readonly active: boolean;
	readonly prefsPath: string;
	readonly updatedAtMs: number;
}

export interface SandDevGatewayOfflineStatus {
	readonly induced: boolean;
}

export type SandOnePasswordCliSource = "system" | "managed";

export type SandOnePasswordCliCandidate =
	| {
			readonly source: SandOnePasswordCliSource;
			readonly path: string;
			readonly state: "missing" | "invalid";
	  }
	| {
			readonly source: SandOnePasswordCliSource;
			readonly path: string;
			readonly state: "ready";
			readonly version: string;
			readonly signature: "verified";
	  };

export type SandOnePasswordCliReadyCandidate = Extract<
	SandOnePasswordCliCandidate,
	{ readonly state: "ready" }
>;

export interface SandOnePasswordCliInspection {
	readonly platformSupported: boolean;
	readonly selected: SandOnePasswordCliReadyCandidate | null;
	readonly candidates: readonly SandOnePasswordCliCandidate[];
	readonly detail: string;
}

export type SandDevOnePasswordCliStatus = SandOnePasswordCliInspection;

export interface SandDevOnePasswordCheckResult {
	readonly isOk: boolean;
	readonly action: "accounts" | "find-vault" | "synthetic-provisioning" | "vaults";
	readonly summary: string;
	readonly accountCount: number;
	readonly vaultCount: number;
	readonly foundDefaultVault: boolean;
}

/** Everything the Dev Controls panel page exchanges with its own Electron main. */
export interface DevControlsRpcContract {
	readonly methods: {
		readonly restartElectron: RpcMethod<Record<string, never>, void>;
		readonly reloadWindow: RpcMethod<Record<string, never>, void>;
		readonly restartOnboarding: RpcMethod<Record<string, never>, void>;
		readonly skipOnboarding: RpcMethod<Record<string, never>, void>;
		readonly themeStatus: RpcMethod<Record<string, never>, SandThemeState>;
		readonly setThemePreference: RpcMethod<
			{ readonly preference: SandThemePreference },
			SandThemeState
		>;
		readonly boxStatus: RpcMethod<Record<string, never>, SandDevBoxStatus>;
		readonly boxHealth: RpcMethod<Record<string, never>, SandDevBoxHealth>;
		readonly upgradeHost: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly pokeHostUpgrade: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly rebuildBox: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly tailLogs: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly startBox: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly teardownBox: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly nukeBox: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly openDesktop: RpcMethod<Record<string, never>, void>;
		readonly boxStoreStatus: RpcMethod<Record<string, never>, SandDevBoxStoreStatus>;
		readonly boxStoreSnapshotNow: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly boxStoreLogs: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly boxStoreRecreateFresh: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly boxStoreClear: RpcMethod<Record<string, never>, SandDevCommandResult>;
		readonly attachProdBoxStatus: RpcMethod<Record<string, never>, AttachProdBoxStatus>;
		readonly setAttachProdBoxEnabled: RpcMethod<
			{ readonly enabled: boolean; readonly isRestartMainApp?: boolean },
			AttachProdBoxStatus
		>;
		readonly setWidgetGallery: RpcMethod<{ readonly isOn: boolean }, void>;
		readonly gatewayOfflineStatus: RpcMethod<Record<string, never>, SandDevGatewayOfflineStatus>;
		readonly setGatewayOffline: RpcMethod<
			{ readonly induced: boolean },
			SandDevGatewayOfflineStatus
		>;
		readonly onePasswordCliStatus: RpcMethod<Record<string, never>, SandDevOnePasswordCliStatus>;
		readonly prepareOnePasswordCli: RpcMethod<Record<string, never>, SandDevOnePasswordCliStatus>;
		readonly cancelOnePasswordCliPrepare: RpcMethod<Record<string, never>, void>;
		readonly onePasswordAccounts: RpcMethod<Record<string, never>, SandDevOnePasswordCheckResult>;
		readonly onePasswordVaults: RpcMethod<Record<string, never>, SandDevOnePasswordCheckResult>;
		readonly onePasswordFindVault: RpcMethod<Record<string, never>, SandDevOnePasswordCheckResult>;
		readonly onePasswordSyntheticProvisioning: RpcMethod<
			Record<string, never>,
			SandDevOnePasswordCheckResult
		>;
	};
	readonly events: Record<string, never>;
	readonly capabilities: never;
	readonly failureCodes: never;
}

export const devControlsRpcContract = declareRpcContract<DevControlsRpcContract>("dev-controls");

export const DEV_CONTROLS_METHOD_TABLE: EdgeMethodTable<DevControlsRpcContract> = {
	restartElectron: { args: "none" },
	reloadWindow: { args: "none" },
	restartOnboarding: { args: "none" },
	skipOnboarding: { args: "none" },
	themeStatus: { args: "none" },
	setThemePreference: { args: "object" },
	boxStatus: { args: "none" },
	boxHealth: { args: "none" },
	upgradeHost: { args: "none" },
	pokeHostUpgrade: { args: "none" },
	rebuildBox: { args: "none" },
	tailLogs: { args: "none" },
	startBox: { args: "none" },
	teardownBox: { args: "none" },
	nukeBox: { args: "none" },
	openDesktop: { args: "none" },
	boxStoreStatus: { args: "none" },
	boxStoreSnapshotNow: { args: "none" },
	boxStoreLogs: { args: "none" },
	boxStoreRecreateFresh: { args: "none" },
	boxStoreClear: { args: "none" },
	attachProdBoxStatus: { args: "none" },
	setAttachProdBoxEnabled: { args: "object" },
	setWidgetGallery: { args: "object" },
	gatewayOfflineStatus: { args: "none" },
	setGatewayOffline: { args: "object" },
	onePasswordCliStatus: { args: "none" },
	prepareOnePasswordCli: { args: "none" },
	cancelOnePasswordCliPrepare: { args: "none" },
	onePasswordAccounts: { args: "none" },
	onePasswordVaults: { args: "none" },
	onePasswordFindVault: { args: "none" },
	onePasswordSyntheticProvisioning: { args: "none" },
};

/** The derived client surface the panel page reads from `window.sand.devControls`. */
export type SandDevControlsBridge = EdgeBridge<DevControlsRpcContract>;
